import React from 'react';
import { render, screen } from '@testing-library/react';
import BeesDeliver from './BeesDeliver';

describe('BeesDeliver', () => {
  test('should render without crashing', () => {
    render(<BeesDeliver />);
    expect(screen.getByTestId('BeesDeliverIcon')).toBeInTheDocument();
  });
  test('should render icon variant without crashing', () => {
    render(<BeesDeliver variant="icon" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Deliver Icon')).toBeInTheDocument();
  });
  test('should render vertical variant without crashing', () => {
    render(<BeesDeliver variant="vertical" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Deliver Vertical Logo')).toBeInTheDocument();
  });
  test('should render with a different colorType without crashing', () => {
    render(<BeesDeliver colorType="onColorBg" />);
    expect(screen.getByTestId('BeesDeliverIcon')).toBeInTheDocument();
  });
});
